-- Portfolio V5: automatic browser-language localization for existing V4 databases.
-- Run in Supabase SQL Editor. Safe to repeat: preserves existing translations and project data.
alter table public.projects add column if not exists translations jsonb not null default '{}'::jsonb;

-- Add translations for the original 12 starter projects when their slugs match.
-- Existing per-language translations take precedence; existing titles, images, categories, etc. stay unchanged.
update public.projects as p
set translations = seed.translations || coalesce(p.translations, '{}'::jsonb)
from (values
  ('lihtech-website', '{"vi":{"subtitle":"Website giới thiệu các giải pháp phần mềm và dịch vụ hỗ trợ công nghệ của LihTech.","description":"LihTech by LihLabs giới thiệu các giải pháp phần mềm và dịch vụ hỗ trợ công nghệ thông tin. Trang giới thiệu dự án tập trung vào thiết kế giao diện, trải nghiệm người dùng và nội dung dịch vụ.","category":"Website doanh nghiệp","role":"Phát triển giao diện / Trình bày UI"},"en":{"subtitle":"A business website presenting software solutions and IT support services from LihTech.","description":"LihTech by LihLabs presents software solutions and IT support services. This portfolio entry highlights the website layout, user experience and service presentation.","category":"Business Website","role":"Frontend Development / UI Presentation"}}'::jsonb),
  ('mori-tea-house', '{"vi":{"subtitle":"Bộ nhận diện và trình bày bao bì cho thương hiệu trà MORI.","description":"Bộ nhận diện thương hiệu và thiết kế bao bì cho MORI TEA HOUSE, theo phong cách nhẹ nhàng và tinh tế. Dự án tập trung vào hệ màu, kiểu chữ, bố cục hình ảnh và ứng dụng thực tế trên bao bì.","category":"Nhận diện thương hiệu","role":"Nhận diện / Thiết kế bao bì"},"en":{"description":"A soft, refined brand identity and packaging concept for MORI TEA HOUSE. The presentation explores color, typography, visual layout and packaging applications.","category":"Brand Identity","role":"Brand Identity / Packaging Design"}}'::jsonb),
  ('lumi-skincare-packaging', '{"vi":{"subtitle":"Thiết kế bao bì và trình bày thương hiệu chăm sóc da LUMI.","description":"Thiết kế bao bì và trình bày thương hiệu mỹ phẩm LUMI theo hướng tự nhiên, mềm mại và hiện đại. Tập trung vào hình ảnh sản phẩm, chất liệu và khả năng ứng dụng nhận diện thương hiệu.","category":"Thiết kế bao bì","role":"Thiết kế bao bì / Chỉ đạo hình ảnh"},"en":{"description":"A skincare packaging and brand presentation exploring natural tones, gentle forms, product materials and cohesive identity applications.","category":"Packaging Design","role":"Packaging Design / Art Direction"}}'::jsonb),
  ('vela-coffee-brand-identity', '{"vi":{"subtitle":"Bộ nhận diện VELA COFFEE và ứng dụng trên ấn phẩm, bao bì.","description":"Dự án nhận diện VELA COFFEE với cách tiếp cận hiện đại, mang tinh thần thương hiệu cà phê. Bộ nhận diện được ứng dụng trên nhiều ấn phẩm và bao bì.","category":"Nhận diện thương hiệu","role":"Nhận diện / Thiết kế bao bì"},"en":{"description":"A modern identity for VELA COFFEE, presented across print materials and packaging applications.","category":"Brand Identity","role":"Brand Identity / Packaging Design"}}'::jsonb),
  ('fast-food', '{"vi":{"subtitle":"Thiết kế đồ họa lấy cảm hứng từ bao bì thức ăn nhanh.","description":"Dự án thiết kế lấy cảm hứng từ fast-food, nhấn mạnh nhịp điệu thị giác, hình khối và sự tương phản trong bố cục.","category":"Thiết kế đồ họa","role":"Thiết kế đồ họa"},"en":{"description":"A graphic design composition inspired by fast-food packaging, emphasizing dynamic layouts, contrast and visual rhythm.","category":"Graphic Design","role":"Graphic Design"}}'::jsonb),
  ('two-coffee-pouch-mockups', '{"vi":{"subtitle":"Bộ mockup hai túi cà phê dành cho trình bày bao bì.","description":"Bộ mockup bao bì cà phê tập trung vào chất liệu, ánh sáng sản phẩm và ứng dụng trong trưng bày thiết kế thương hiệu.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"Coffee pouch packaging mockups exploring material realism, product lighting and brand presentation.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('coffee-bags-mockups', '{"vi":{"subtitle":"Bộ mockup túi cà phê với cách trình bày tối giản.","description":"Bộ mockup túi cà phê với bố cục rõ ràng, mô phỏng sản phẩm và tạo bối cảnh ứng dụng cho thiết kế bao bì.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"A set of coffee bag mockups with clean layouts emphasizing packaging visualization and practical product presentation.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('beverage-can-mockup', '{"vi":{"subtitle":"Mockup bao bì lon nước giải khát trong không gian ngoài trời.","description":"Bộ mockup lon nước giải khát sử dụng bối cảnh ngoài trời để tăng chiều sâu và độ chân thực của hình ảnh sản phẩm.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"Beverage can mockups shown in an outdoor setting, exploring depth and realistic product presentation.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('coffee-paper-cup-mockup-on-table', '{"vi":{"subtitle":"Mockup ly giấy cà phê theo phong cách editorial.","description":"Bộ mockup ly giấy cà phê tập trung vào góc chụp, ánh sáng và cách ứng dụng hình ảnh vào bộ nhận diện thương hiệu.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"An editorial coffee paper-cup mockup with attention to composition, lighting and identity applications.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('food-bag-mockup', '{"vi":{"subtitle":"Thiết kế mockup túi giấy đựng thực phẩm.","description":"Mockup túi giấy thực phẩm được trình bày theo bố cục gọn gàng, giúp làm rõ hình thức sản phẩm và ứng dụng thương hiệu.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"A neat product-focused food paper-bag mockup showing packaging form and branding applications.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('kraft-paper-bags-mockup', '{"vi":{"subtitle":"Mockup túi giấy kraft cho bộ nhận diện sản phẩm.","description":"Bộ mockup túi giấy kraft với bố cục tối giản và gam màu trung tính, phù hợp với trình bày sản phẩm tiêu dùng.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"A series of kraft paper-bag mockups with neutral tones and minimalist compositions for consumer-product presentations.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb),
  ('small-yogurt-cup-mockup', '{"vi":{"subtitle":"Mockup hũ sữa chua với trọng tâm là hình dáng sản phẩm.","description":"Bộ mockup hũ sữa chua chú trọng hình khối, bề mặt in ấn và cách trưng bày sạch sẽ của sản phẩm.","category":"Mockup bao bì","role":"Thiết kế mockup bao bì"},"en":{"description":"A small yogurt-cup mockup focused on shape, printable surfaces and clean product presentation.","category":"Packaging Mockup","role":"Packaging Mockup Design"}}'::jsonb)
) as seed(slug,translations)
where p.slug=seed.slug;

-- No new RLS policies are required; existing administrator policies continue to apply.
